export const methodIntroductions:Record<string,MethodIntroduction> = {
  ancova:{
    idea:['ANCOVA compares group means while including covariates such as a baseline score. Its adjusted means describe groups at specified covariate values; they are not the raw group averages. The model combines group comparisons with regression.','ANCOVA 在比較組別平均數時納入協变量，例如前測分數。調整後平均數描述指定協变量數值下的組別，並非原始平均數；它結合組別比較與迴歸。'],
    question:['Do two teaching groups differ in post-test writing scores when compared at the same baseline writing score?','在相同前測寫作分數下，兩種教學組別的後測寫作平均分是否不同？'],
    read:['Read the adjusted group contrast, its units and interval, alongside group n, raw summaries and covariate definitions. If the group-by-baseline interaction matters, describe how the group difference changes with baseline rather than giving one common contrast.','一起閱讀調整後組別差值、單位及區間，以及各組 n、原始摘要與協变量定義。若組別與前測有交互作用，應說明差異如何隨前測改變，而非只報一個共同差值。'],
    check:['Inspect overlap in baseline scores and the assumed relationship with the outcome. Adjustment cannot remove every confounder; adjusting for a variable caused by the intervention can change the question or introduce bias.','檢查前測分數是否重疊，以及它與結果的模型關係。調整不能消除所有混淆；若調整介入後產生的变量，可能改變問題或引入偏差。'],
    contrast:['ANOVA compares means without those covariates. Multiple regression expresses the same ANCOVA model using coded group predictors.','ANOVA 不納入這些協变量；多元迴歸可用組別編碼表達同一 ANCOVA 模型。'],related:['anova','regression'],sources:['ucla','fein5']},
  manova:{
    idea:['MANOVA asks about group differences in several continuous outcomes together. It uses their relationships as well as their separate means. MANCOVA adds covariates to this joint comparison. A multivariate result is not a separate significant result for every outcome.','MANOVA 把多個連續結果一起比較組別，既考慮各自平均數，也考慮結果之間的關係。MANCOVA 再納入協变量；多变量顯著不表示每個結果都顯著。'],
    question:['Do instruction groups differ in their combined pattern of speaking fluency, accuracy and complexity?','不同教學組別在口語流利度、準確度與複雜度的整體模式上是否不同？'],
    read:['Name the outcome set and multivariate statistic, such as Pillai’s trace, with its test, df and p. Then read justified outcome-specific follow-ups, effect sizes and multiplicity decisions, supported by each group’s summaries.','交代結果組合與多变量統計量，例如 Pillai 軌跡，以及檢定、df 與 p；再讀有理據的單項後續比較、效應量及多重比較安排，並配合各組摘要。'],
    check:['Check independent cases, group sizes, unusual multivariate observations and covariance assumptions. Highly redundant outcomes or too little information for the outcome set can make estimation unstable.','檢查個案獨立性、組別人數、多变量異常值及協方差假設。結果過度重複，或資訊不足以支撐多個結果時，估計可能不穩定。'],
    contrast:['Use separate ANOVAs for clearly separate questions with an explicit multiplicity plan; use MANOVA when the joint outcome question is substantively meaningful.','若各問題獨立且有多重比較計劃，可分別使用 ANOVA；若聯合結果本身有研究意義，可考慮 MANOVA。'],related:['anova','ancova'],sources:['ucla']},
  rank:{
    idea:['Rank tests replace numerical distances with ordering. Mann–Whitney compares two independent groups; Wilcoxon signed-rank preserves pairs; Kruskal–Wallis compares several independent groups. Choosing a rank test still requires a clear hypothesis and observation design.','秩次檢定以排序取代數值距離。Mann–Whitney 比較兩個獨立組；Wilcoxon 符號秩檢定保留配對；Kruskal–Wallis 比較多個獨立組。仍須明確界定假設及觀察設計。'],
    question:['Do ordinal satisfaction responses tend to be higher in one independent group than in another?','某個獨立組別的序位滿意度反應，是否傾向高於另一組？'],
    read:['Report the exact test, group summaries and n, statistic, p and a suitable named effect size. A median comparison needs additional distributional assumptions; a rank-test result is not automatically evidence about medians alone.','報告確切檢定、組別摘要與 n、統計量、p 及適當的具名效應量。若要解釋為中位數比較，還需要額外分佈假設；秩次結果不會自動只針對中位數。'],
    check:['Check pairing, independence, ties and the assumptions of the particular test. Signed-rank interpretation requires attention to the symmetry of paired differences. Nonparametric does not mean assumption-free.','檢查配對、獨立性、同秩及該檢定的假設；符號秩解讀須留意配對差值的對稱性。「非參數」並非「沒有假設」。'],
    contrast:['A t-test targets means; rank procedures target specified ordering or distributional hypotheses. Select by the question, not by a normality-test p-value alone.','t 檢定針對平均數；秩次程序針對指定的排序或分佈假設。按問題選擇，不應只靠常態檢定的 p。'],related:['ttest','anova'],sources:['fein9']},
  equivalence:{
    idea:['Equivalence testing asks whether a difference is small enough to fall within meaningful bounds chosen before analysis. TOST uses two one-sided tests: one rules out a difference below the lower bound and the other rules out one above the upper bound.','等效性檢定問差異是否小至落在分析前訂定、有實質意義的界限內。TOST 包含兩個單側檢定，分別排除低於下界與高於上界的差異。'],
    question:['Are online and classroom test scores similar enough that differences smaller than three points would not affect the intended decision?','若少於三分的差異不影響預定決策，網上與面授測驗分數是否足夠相近？'],
    read:['State the bounds and their justification. At α = .05, conventional TOST supports equivalence when the corresponding 90% CI lies wholly inside the bounds. Show the estimate and interval, not only an “equivalent” label.','列明界限及理據。在 α = .05 時，傳統 TOST 的相應 90% CI 完全位於等效界限內才支持等效；應呈現估計與區間，不只貼上「等效」標籤。'],
    check:['A non-significant difference test does not establish equivalence. Wide intervals can leave both difference and equivalence unresolved. Bounds must reflect the use of the measure, rather than being chosen to fit the result.','差異檢定不顯著不能確立等效。區間太寬時，差異與等效都可能未能判定。界限須反映測量用途，而非按結果挑選。'],
    contrast:['A usual t-test asks about zero difference; equivalence testing asks about a prespecified interval of practically small differences.','一般 t 檢定問差異是否為零；等效性檢定問差異是否位於事先界定的實質小差異區間。'],related:['ttest'],sources:['equivalence']},
  regression:{
    idea:['Linear regression describes the expected outcome at specified predictor values. Multiple regression includes several predictors; each coefficient is conditional on the others. Hierarchical regression adds theory-led blocks to compare what each block contributes to the specified model.','線性迴歸描述指定預測变量數值下的結果期望值。多元迴歸納入多個預測变量，各係數以其餘变量為條件；分塊迴歸按理論順序投入变量組，比較各組對模型的貢獻。'],
    question:['How is weekly practice related to writing scores after accounting for baseline proficiency and course group?','在考慮起始能力與課程組別後，每週練習量與寫作分數有何關係？'],
    read:['Read b in original units, its interval and reference category before p. Report the model’s R² and residual diagnostics. For blocks, identify their order and ΔR²; this depends on what was entered earlier.','先讀原單位的 b、區間與參照類別，再讀 p；報告模型 R² 及殘差診斷。若分塊投入，要說明次序與 ΔR²，因其取決於先前投入的变量。'],
    check:['Inspect functional form, residual variation, dependence, influential cases and collinearity. Predictors need not themselves be normally distributed. Adjusted association and high R² do not establish causation.','檢查函數形式、殘差方差、依賴、影響大的個案及共線性；預測变量本身毋須常態分佈。調整後關聯或高 R² 均不能確立因果。'],
    contrast:['Correlation summarises one pair symmetrically. Regression specifies an outcome and conditions its expected value on predictors. Hierarchical regression is not multilevel modelling.','相關對稱地概括一對变量；迴歸指定結果並以預測变量為條件。分塊迴歸不等於多層模型。'],related:['correlation','mixed'],sources:['fein5']},
  logistic:{
    idea:['Binary logistic regression models an event coded 1 versus a non-event coded 0. The model works on log odds; predictions can be expressed as probabilities between 0 and 1. Predictors may be numerical, categorical or both.','二元邏輯斯迴歸分析編碼為 1 的事件與編碼為 0 的非事件。模型以對數勝算運作，預測可轉為 0 至 1 的機率；預測变量可為數值、類別或兩者。'],
    question:['Is course completion associated with baseline proficiency and weekly participation?','課程是否完成，與起始能力及每週參與有何關係？'],
    read:['State what 1 means and the reference categories. Read odds ratios and their intervals; OR = 2 means twice the odds, not twice the probability. Predicted probabilities at meaningful predictor values make the result easier to explain.','說明 1 代表甚麼及參照類別，閱讀勝算比與區間；OR = 2 指勝算為兩倍，不是機率為兩倍。呈現有意義條件下的預測機率，有助解釋結果。'],
    check:['Check sparse categories, separation, information in both outcomes, dependence and the form of continuous predictors on the log-odds scale. For prediction, also assess calibration and performance on new cases.','檢查稀少類別、完全分離、兩種結果的資訊、依賴，以及連續預測变量與對數勝算的形式。若用於預測，亦須檢查校準及新個案表現。'],
    contrast:['Chi-square tests an unadjusted table association. Logistic regression can include several predictors and produce conditional odds or probabilities.','卡方檢驗未調整的列聯表關聯；邏輯斯迴歸可納入多個預測变量，估計條件勝算或機率。'],related:['chi','ordinal'],sources:['logistic']},
  ordinal:{
    idea:['Ordinal regression retains the order of categories without assuming equal spacing. A proportional-odds model shares slopes across cumulative category splits. Multinomial regression handles unordered outcomes by comparing each category with a named reference category.','序位迴歸保留類別次序，但不假設間距相等。比例勝算模型在累積類別分界之間共用斜率；多項迴歸則處理無序結果，逐一與指定參照類別比較。'],
    question:['Do practice habits relate to low, medium or high confidence? For a choice of video, text or audio, is an unordered-category model more appropriate?','練習習慣是否與低、中、高信心有關？若結果是選影片、文字或音訊，是否應使用無序類別模型？'],
    read:['Name the outcome ordering, reference and link. Interpret coefficients using that exact coding and show predicted category probabilities. In multinomial models, each non-reference category has its own comparison; do not pool those coefficients into one slope.','說明類別次序、參照與連結函數，依確切編碼解讀係數，並呈現各類別預測機率。多項模型的各非參照類別有自己的比較，不應合併成一條斜率。'],
    check:['Check proportional odds when assumed, sparse cells and dependence. If the shared-slope assumption is unsuitable, consider a justified alternative rather than treating category codes as continuous scores.','若假設比例勝算，須檢查此假設，以及稀少格數與依賴；若共用斜率不適合，應選有理據的替代模型，不應直接把類別代碼當連續分數。'],
    contrast:['Binary logistic regression has two outcome categories. Ordinal models use order; multinomial models do not impose it.','二元邏輯斯迴歸只有兩種結果；序位模型使用次序，多項模型則不強加次序。'],related:['logistic'],sources:['ordinal']},
  count:{
    idea:['Count regression models how many events occur. Poisson regression links predictors to a non-negative expected count; negative-binomial regression allows extra variability. If observation periods differ, an exposure offset can make the target a rate rather than a raw count.','計數迴歸分析事件發生多少次。Poisson 模型把預測变量連到非負期望次數；負二項模型容許額外離散。觀察時段不同時，可用暴露量偏移項，使目標成為率而非原始次數。'],
    question:['How is the number of questions asked related to proficiency, allowing for different numbers of lessons observed?','在考慮觀察課堂數不同後，提問次數與能力有何關係？'],
    read:['Report the observation window, exposure and distribution. An exponentiated log-link coefficient is a multiplicative count or rate ratio; identify which. Read it with an interval and predicted counts or rates.','報告觀察期間、暴露量及分佈。對數連結係數取指數後，表示次數或率的倍數比；要說明是哪一種，並配合區間與預測次數或率。'],
    check:['Inspect overdispersion, excess zeros, clustering and exposure measurement. Many zeros do not automatically justify a zero-inflated model; the proposed process should make sense.','檢查過度離散、過多零、群集及暴露量測量。零很多不會自動合理化零膨脹模型；提出的資料生成過程須有意義。'],
    contrast:['Logistic regression asks whether an event occurs. Count regression asks how often; survival models ask when it first occurs.','邏輯斯迴歸問有沒有發生；計數迴歸問多少次；存活分析問何時首次發生。'],related:['logistic','survival'],sources:['count']},
  gam:{
    idea:['A GAM allows a relationship to bend smoothly instead of requiring one straight slope. A smoothness penalty balances following the data against excessive wiggles. The model can also include ordinary linear terms and response distributions beyond continuous scores.','GAM 容許關係平滑彎曲，不必用一條固定斜率直線。平滑懲罰在貼近資料與過度起伏之間取得平衡；亦可加入一般線性項及適合不同結果的分佈。'],
    question:['Does the association between practice time and performance rise quickly at first and then level off?','練習時間與表現的關聯，是否先迅速上升、其後趨於平緩？'],
    read:['Start with the fitted curve, uncertainty band and range of observed data. Effective degrees of freedom describe smooth complexity, not effect size. Report the family, link and smoothing approach; a single coefficient may not summarise the curve.','先看擬合曲線、不確定性帶及實際資料範圍。有效自由度描述平滑複雜度，並非效應量；須報分佈族、連結與平滑方式，不能只用一個係數概括曲線。'],
    check:['Check residuals, adequacy of the smooth basis, dependence and unsupported extrapolation. Repeated observations may need random effects or a GAMM; flexibility does not remove design requirements.','檢查殘差、平滑基底是否足夠、依賴及缺乏資料支持的外推。重複觀察可能需要隨機效應或 GAMM；模型有彈性不代表可忽略設計。'],
    contrast:['Linear regression uses specified straight-line terms; GAMs estimate smooth terms. A mixed model additionally represents grouping or repetition.','線性迴歸使用指定的直線項；GAM 估計平滑項。混合模型再表達分組或重複觀察。'],related:['regression','mixed'],sources:['gam']},
  robust:{
    idea:['Robust regression changes the estimation rule so some unusual residuals have less influence than in ordinary least squares. Different robust estimators protect against different problems; the word “robust” alone does not specify the model.','穩健迴歸改變估計規則，減少某些異常殘差相對於普通最小平方法的影響。不同穩健估計法針對不同問題；單說「穩健」不足以界定模型。'],
    question:['Is the estimated practice–score relationship sensitive to a few unusually large residuals?','練習量與分數的估計關係，是否容易受到少數極大殘差影響？'],
    read:['Name the estimator and tuning choices. Compare coefficient direction, magnitude and uncertainty with a justified baseline model. Describe which observations receive reduced weight and investigate why, rather than hiding them.','列明估計法及調整選擇，與有理據的基準模型比較係數方向、大小及不確定性。交代哪些觀察被降低權重並查明原因，不應把它們隱藏。'],
    check:['A real but unusual case is not necessarily an error. Robust regression does not automatically solve leverage, confounding, clustering or a wrong functional form.','真實但特殊的個案不一定是錯誤。穩健迴歸不會自動處理高槓桿、混淆、群集或錯誤函數形式。'],
    contrast:['Robust regression can change coefficient estimates. Robust standard errors usually change uncertainty estimates while keeping the original coefficient estimator.','穩健迴歸可能改變係數估計；穩健標準誤通常保留原係數估計法，只改變不確定性的估計。'],related:['regression'],sources:['robust']},
  mediation:{
    idea:['A mediation model represents X relating to an intermediate variable M, which in turn relates to Y. In a simple linear model without interactions, the indirect component is the product of the two path coefficients. A fitted pathway is a statistical representation, not direct observation of a mechanism.','中介模型表達 X 與中介变量 M 有關，而 M 再與 Y 有關。在沒有交互作用的簡單線性模型中，間接成分為兩條路徑係數的乘積。擬合路徑是統計表達，不等於直接觀察到機制。'],
    question:['Is the relationship between feedback and writing performance represented partly through later revision effort?','回饋與寫作表現的關係，是否部分透過其後的修改投入表達？'],
    read:['Identify X, M, Y and measurement timing. Read the indirect estimate and its interval, plus the direct component and model specification. A significant total association is not a prerequisite for estimating an indirect component.','確認 X、M、Y 及測量時間，閱讀間接估計及區間，同時看直接成分與模型設定。估計間接成分，並不必先有顯著總關聯。'],
    check:['Causal mediation needs justified ordering and confounding assumptions for the pathways. Simultaneous self-report measures cannot by themselves establish that M transmitted an effect.','因果中介需要有理據的時間順序及路徑混淆假設。同時收集的自陳量度，本身不能確立 M 傳遞了效果。'],
    contrast:['Mediation asks about an intermediate pathway. Moderation asks whether a relationship changes across conditions.','中介問是否有中間路徑；調節問關係是否隨條件改變。'],related:['moderation','conditional'],sources:['fein7']},
  moderation:{
    idea:['Moderation is an interaction: the relationship between X and Y depends on W. The model includes the component terms and their interaction. It can represent differences between groups or changes across a continuous moderator.','調節就是交互作用：X 與 Y 的關係取決於 W。模型包含各組成項及其交互作用，可表達組別間差異，或關係隨連續調節变量而改變。'],
    question:['Is practice more strongly associated with speaking performance for learners with lower initial confidence?','練習與口語表現的關聯，是否在起始信心較低的學習者中較強？'],
    read:['Read the interaction estimate, interval and a plot of predicted outcomes. Explain conditional slopes at meaningful W values within the data range. The main X coefficient describes its slope at the coded W = 0, not necessarily its average relationship.','閱讀交互作用估計、區間與預測結果圖，並解釋資料範圍內有意義 W 數值下的條件斜率。X 主係數指編碼 W = 0 時的斜率，不一定是平均關係。'],
    check:['“Significant in one group, non-significant in another” is not itself a test of their difference. Avoid splitting a continuous moderator into arbitrary high/low groups.','「一組顯著、另一組不顯著」本身不是組間差異的檢定。避免隨意把連續調節变量切成高低組。'],
    contrast:['Adding W only as a covariate adjusts the model. Adding X-by-W asks whether the slope itself changes with W.','只把 W 作協变量是調整；加入 X 與 W 的交互項，才問斜率是否隨 W 改變。'],related:['mediation','regression'],sources:['fein7']},
  conditional:{
    idea:['Conditional process models combine an indirect pathway with an interaction. The indirect association can vary because the X-to-M path, the M-to-Y path, or both depend on a moderator. The moderated path must follow the research rationale.','條件歷程模型結合間接路徑與交互作用。若 X 至 M、M 至 Y，或兩條路徑取決於調節变量，間接關聯便可能隨之改變；要由研究理據決定調節哪條路徑。'],
    question:['Does feedback relate to performance through revision effort differently at different levels of teacher support?','在不同教師支持水平下，回饋透過修改投入與表現的間接關聯是否不同？'],
    read:['Specify exactly which path is moderated. Report conditional indirect estimates at meaningful moderator values and their intervals; where applicable, examine an index of moderated mediation with its interval.','明確列出哪條路徑受調節，報告有意義調節值下的條件間接估計及區間；適用時，檢視調節式中介指數及其區間。'],
    check:['Different significance labels for two conditional indirect effects do not establish that they differ. Model complexity requires adequate information, and causal claims retain the demanding assumptions of mediation.','兩個條件間接效應的顯著標籤不同，不能證明它們有差異。複雜模型須有足夠資訊；因果主張仍需符合中介分析的嚴格假設。'],
    contrast:['Ordinary mediation gives an indirect component under its specified model. Conditional process asks how that component varies with a moderator.','一般中介提供指定模型下的間接成分；條件歷程再問該成分如何隨調節变量改變。'],related:['mediation','moderation'],sources:['hayes','fein7']},
  efa:{
    idea:['EFA explores common dimensions that could explain why items covary. Items may relate to more than one factor, and factors may correlate. The analyst chooses an extraction approach, factor count and rotation; the data do not simply reveal named constructs automatically.','EFA 探索可解釋項目協方差的共同維度。項目可同時與多個因素有關，因素亦可相關；分析者須選抽取法、因素數與轉軸，資料不會自動揭示已有名稱的構念。'],
    question:['Do questionnaire items about planning, monitoring and reflection suggest distinguishable dimensions of self-regulation?','有關計劃、監察與反思的問卷項目，是否提示可區分的自我調節維度？'],
    read:['Read the loading pattern, cross-loadings, communalities and factor correlations together. Report how factor count was chosen, including parallel analysis where appropriate, and explain item content before naming a factor.','一起閱讀負荷模式、跨負荷、共同性與因素相關。報告因素數如何決定，適當時包括平行分析；先解釋項目內容，再為因素命名。'],
    check:['Match the association matrix and estimator to item responses. Small or poorly supported factors can be unstable. Avoid deleting items solely to obtain neat loadings, and evaluate the proposed structure in further data.','關聯矩陣及估計法須配合項目反應。資訊不足的因素可能不穩定；避免只為得到整齊負荷而刪題，並用其他資料評估提出的結構。'],
    contrast:['EFA explores measurement structure. CFA evaluates a prespecified structure; PCA summarises observed variance without the same common-factor model.','EFA 探索測量結構；CFA 評估預定結構；PCA 概括觀察方差，並不使用同一共同因素模型。'],related:['cfa','pca'],sources:['fein8']},
  cfa:{
    idea:['CFA starts with a specified measurement model: which items indicate which factors and which relationships are allowed. It asks whether that model can reproduce the observed associations sufficiently well, while estimating loadings, factor relations and residual variation.','CFA 從指定測量模型開始：哪些項目反映哪些因素，以及容許哪些關係。它評估模型能否充分重現觀察關聯，並估計負荷、因素關係及殘差方差。'],
    question:['Is a proposed three-factor self-regulation questionnaire compatible with responses from this student sample?','提出的三因素自我調節問卷，是否與這批學生的反應相容？'],
    read:['Read loadings, factor correlations and local residuals as well as χ², CFI/TLI, RMSEA with its interval and SRMR. Explain the estimator, factor scaling and any respecification; a cutoff checklist is insufficient.','閱讀負荷、因素相關與局部殘差，以及 χ²、CFI／TLI、RMSEA 及區間、SRMR。交代估計法、因素尺度與重新設定；只對照界值並不足夠。'],
    check:['Check identification, convergence and improper estimates such as negative residual variances. Match estimation to ordinal items where needed. Good fit does not prove the model is the only valid structure.','檢查識別、收斂，以及負殘差方差等不適當估計；需要時配合序位項目選估計法。良好擬合不能證明此模型是唯一有效結構。'],
    contrast:['EFA permits a more exploratory loading pattern. CFA imposes specific measurement restrictions; SEM adds structural relations between variables or factors.','EFA 容許較探索性的負荷模式；CFA 施加特定測量限制；SEM 再加入变量或因素間的結構關係。'],related:['efa','sem'],sources:['cfa']},
  pca:{
    idea:['PCA replaces many observed variables with weighted components. The first component captures as much observed variance as possible; later components capture remaining variance and are orthogonal in standard PCA. Components are mathematical summaries, not automatically psychological traits.','PCA 以加權主成分取代多個觀察变量。第一成分盡量概括最多觀察方差，其後成分概括剩餘方差，標準 PCA 的成分互相正交。成分是數學摘要，不會自動等同心理特質。'],
    question:['Can a large set of language-feature measures be summarised by a few components before exploratory plotting?','能否先用少數主成分概括大量語言特徵，再作探索圖形？'],
    read:['Report scaling choices, retained component count, loadings and variance captured. Explain what a high component score combines. Keep preprocessing and component fitting within training data when PCA feeds a predictive model.','報告尺度處理、保留成分數、負荷與概括的方差，說明高成分分數結合了甚麼。若 PCA 用於預測模型，預處理及成分擬合須限於訓練資料。'],
    check:['Variables with larger numerical scales can dominate an unscaled analysis. A large variance proportion does not establish validity or guarantee that the components retain information relevant to the research outcome.','未標準化時，數值尺度較大的变量可能主導分析。概括很多方差不代表具有效度，亦不保證保留了與研究結果相關的資訊。'],
    contrast:['PCA summarises total observed variance. EFA models shared covariance through common factors and separate item-specific variation.','PCA 概括總觀察方差；EFA 透過共同因素及分開的項目特有方差，分析指標間的協方差。'],related:['efa','cluster'],sources:['pca']},
  sem:{
    idea:['SEM estimates a system of linked relationships. Observed-variable path models use measured scores; latent-variable SEM also models how indicators measure constructs. Drawing arrows specifies a model to examine, rather than demonstrating causal direction.','SEM 估計一組相連關係。觀察变量路徑模型使用測得分數；潛在变量 SEM 亦建模指標如何測量構念。畫箭頭是提出待評估模型，不是證明因果方向。'],
    question:['Is a model linking support, engagement and achievement compatible with the data while representing engagement with several indicators?','若用多個指標表達投入，支持、投入與成就的關係模型是否與資料相容？'],
    read:['Evaluate the measurement part before interpreting structural paths. Report model identification, estimator, fit, coefficients and intervals. Distinguish unstandardised from standardised paths, direct from indirect components, and planned from modified models.','解讀結構路徑前先評估測量部分。報告識別、估計法、擬合、係數與區間，區分未標準化與標準化路徑、直接與間接成分、預定與修改後模型。'],
    check:['Check convergence, improper estimates and plausible alternatives. Zero-df models cannot have their restrictions tested by global fit. A well-fitting model may still be causally wrong or observationally equivalent to another model.','檢查收斂、不適當估計及合理替代模型。零自由度模型不能用整體擬合檢驗其限制；擬合良好仍可能因果設定錯誤，或與另一模型在觀察上等價。'],
    contrast:['CFA focuses on measurement. SEM can include that measurement model and a system of regressions; using SEM does not itself improve causal identification.','CFA 聚焦測量；SEM 可結合測量模型與一組迴歸，但採用 SEM 本身不會改善因果識別。'],related:['cfa','mediation'],sources:['sem']},
  invariance:{
    idea:['Measurement invariance asks whether a scale operates comparably across groups or occasions. Configural models share a factor pattern; metric models constrain loadings; scalar models also constrain intercepts, with corresponding threshold restrictions for ordinal items. The exact sequence depends on the measurement model.','測量恆等性問量表在不同組別或時點是否可比。形態模型共用因素模式；度量模型限制負荷相等；截距模型再限制截距，序位題則需相應閾值限制。確切步驟取決於測量模型。'],
    question:['Can confidence scores be compared across language groups, or do some items function differently?','不同語言組別的信心分數可否比較，還是部分項目的運作不同？'],
    read:['State which parameters were constrained and compare appropriately estimated models. Examine changes in fit and local misfit together. For latent mean comparisons, justify the relevant intercept or threshold equality assumptions and any partial invariance.','說明限制了哪些參數，並用適當估計方式比較模型。綜合閱讀擬合變化與局部不擬合。比較潛在平均數時，須論證相關截距或閾值相等假設及部分恆等性。'],
    check:['A non-significant test is not proof of identical measurement. Sample size, model fit and the location of non-invariance matter; a single universal ΔCFI rule cannot decide every case.','檢定不顯著不是測量完全相同的證明。樣本量、模型擬合及不恆等的位置均重要，不能單靠通用 ΔCFI 規則決定。'],
    contrast:['Reliability concerns score consistency. Invariance concerns whether measurement parameters support the intended comparison across groups or time.','信度關乎分數一致性；恆等性關乎測量參數能否支持預定的跨組或跨時比較。'],related:['cfa','reliability'],sources:['invariance']},
  reliability:{
    idea:['Reliability concerns consistency under specified measurement conditions. Internal consistency addresses how items contribute to a score; rater reliability addresses reproducibility across raters. These are different questions and require different coefficients.','信度關乎指定測量條件下的一致性。內部一致性問各項目如何支持一個分數；評分者信度問跨評分者的可重現性。兩者問題不同，須使用不同係數。'],
    question:['Do the questionnaire items support a consistent score? Separately, would two raters give sufficiently similar speaking scores?','問卷項目能否支持一致的分數？另外，兩名評分者的口語評分是否足夠相近？'],
    read:['Name alpha or the specific omega, score composition and sample. For ICC, specify the rater design, agreement versus consistency, and single versus average ratings, with an interval. Use kappa-type measures when appropriate for categorical agreement.','列明 alpha 或具體 omega、分數組成及樣本。ICC 要交代評分設計、絕對一致或一致性、單次或平均評分，以及區間；類別一致性則按需要使用 kappa 類量數。'],
    check:['High alpha does not prove one factor or validity; redundant items can inflate it. A high correlation between two raters can coexist with a systematic scoring difference. Avoid automatic item deletion just to raise a coefficient.','高 alpha 不能證明單一因素或效度，重複項目可把它提高。兩名評分者高度相關，仍可能有系統評分差異；不要只為提高係數而自動刪題。'],
    contrast:['Factor analysis examines measurement structure. Reliability evaluates a particular score under a specified design; neither substitutes for broader validity evidence.','因素分析檢視測量結構；信度評估特定設計下的特定分數，兩者均不能取代較全面的效度證據。'],related:['efa','invariance'],sources:['fein8','omega','icc']},
  irt:{
    idea:['IRT models response probabilities through a latent trait and item properties. For binary items, difficulty locates an item on the trait scale and discrimination describes how sharply its response probability changes. Polytomous models handle responses with several ordered categories.','IRT 以潛在特質及項目特性分析反應機率。二元題的難度定位項目在特質尺度上的位置，鑑別度描述機率改變有多陡；多分類模型處理多個有序反應類別。'],
    question:['Which reading items provide information for lower-proficiency learners, and which distinguish learners at higher levels?','哪些閱讀題為較低能力學習者提供資訊，哪些較能區分高能力者？'],
    read:['Read item-response curves, parameter definitions, item/test information and trait-score uncertainty. Explain the chosen model and scale identification. Item difficulty is model-specific; it is not simply the observed percentage answering correctly.','閱讀項目反應曲線、參數定義、項目／測驗資訊及特質分數不確定性，交代模型與尺度識別。項目難度依模型定義，並非直接等於答對百分比。'],
    check:['Examine dimensionality, local dependence, item fit, differential item functioning and calibration support. Linking forms requires defensible anchors; a model’s invariance properties require adequate fit.','檢查維度、局部依賴、項目擬合、差異項目功能及校準資訊。不同試卷連結需要合理錨題；模型的恆等性特性須以足夠擬合為前提。'],
    contrast:['Classical item summaries describe performance in the sample. IRT relates responses to an explicit trait model and allows precision to vary across the trait range.','古典項目摘要描述樣本表現；IRT 把反應連到明確特質模型，並容許精確度隨特質位置改變。'],related:['cfa','reliability'],sources:['irt']},
  cluster:{
    idea:['Clustering groups cases by similarity across selected variables. K-means seeks compact groups around centres; hierarchical clustering repeatedly combines or divides groups according to a distance and linkage rule. Neither needs an outcome label supplied in advance.','分群按選定变量上的相似性把個案分組。K 平均數尋找圍繞中心的緊密群組；階層分群依距離與連結規則逐步合併或分割群組，毋須事先提供結果標籤。'],
    question:['Do learners show recurring combinations of online participation, practice frequency and help-seeking?','學習者在網上參與、練習頻率與求助方面，是否出現反覆可見的組合？'],
    read:['Describe input variables, scaling, distance, algorithm and group count. Read cluster sizes and within-cluster patterns, then examine stability under alternative starts or samples. Name groups from their observed patterns, not assumed personalities.','交代輸入变量、標準化、距離、算法及群數，閱讀群組大小與組內模式，再檢視不同起點或樣本下的穩定性。依觀察模式命名，不要假定人格類型。'],
    check:['Scaling and redundant features can dominate the result. Every algorithm can produce a partition even when no strong grouping exists; a tidy plot alone does not establish meaningful types.','尺度及重複特徵可能主導結果。即使沒有明顯分群結構，算法也能產生劃分；圖形整齊不代表類型有實質意義。'],
    contrast:['Clustering applies an algorithmic similarity rule. LPA and LCA specify mixture distributions and estimate uncertain membership probabilities.','分群使用算法上的相似規則；LPA 與 LCA 指定混合分佈並估計帶不確定性的歸屬機率。'],related:['lpa','lca'],sources:['cluster']},
  lpa:{
    idea:['LPA represents continuous indicators as a mixture of latent profiles. Each profile has modelled means and variances, and each person has probabilities of membership. Profiles summarise patterns across indicators; they are not directly observed categories.','LPA 把連續指標表達為潛在剖面的混合。各剖面有模型化平均數與方差，各人則有歸屬機率；剖面概括跨指標模式，並非直接觀察的類別。'],
    question:['Are there distinct patterns of confidence, enjoyment and anxiety rather than one overall high-to-low motivation scale?','信心、愉悅與焦慮是否形成不同組合，而非只沿一條整體動機高低尺度排列？'],
    read:['Compare plausible profile counts using information criteria, replicated best likelihoods, profile size and substantive interpretation. Plot the indicator means. Report classification uncertainty; entropy describes separation and cannot by itself choose the number of profiles.','用資訊準則、最佳似然是否重現、剖面大小及實質解釋，比較合理剖面數；繪出指標平均數並報分類不確定性。熵描述分離程度，不能單獨決定剖面數。'],
    check:['Distributional shape, outliers, scaling and within-profile covariance restrictions can create or change profiles. Account for classification error when relating profiles to external outcomes.','分佈形狀、離群值、尺度及剖面內協方差限制可能產生或改變剖面；把剖面連到外部結果時，須處理分類誤差。'],
    contrast:['Use LPA for continuous indicators and LCA for categorical indicators. A profile label does not demonstrate a fixed learner identity.','LPA 使用連續指標，LCA 使用類別指標；剖面名稱不能證明學習者有固定身分類型。'],related:['lca','cluster'],sources:['lpa']},
  lca:{
    idea:['LCA represents patterns of categorical responses through latent classes. The model estimates class proportions and response probabilities within each class. A learner’s complete response pattern contributes to uncertain class membership; one answer does not determine a class with certainty.','LCA 透過潛在類別表達類別反應模式，估計類別比例與各類別內的反應機率。完整反應模式用來估計帶不確定性的歸屬；單一答案不能確定一人的類別。'],
    question:['Do yes/no responses about planning, peer help and online practice suggest recurring learner strategy patterns?','計劃、同儕求助與網上練習的是／否反應，是否提示反覆出現的策略模式？'],
    read:['Read class-specific response-probability profiles alongside class sizes. Compare class counts, fit, repeated starts and classification uncertainty. A high probability of an item response within a class is different from a person’s probability of belonging to that class.','把類別內反應機率模式與類別大小一起閱讀，並比較類別數、擬合、重複起點及分類不確定性。類別內某項反應機率高，不等於某人屬於該類別的機率高。'],
    check:['Check whether local independence within classes is plausible. Residual item dependence or sparse response patterns can distort the class solution; avoid treating assigned classes as error-free observations.','檢查類別內局部獨立是否合理。項目剩餘依賴或稀少反應模式可能扭曲分類；不要把指派類別當作沒有誤差的觀察。'],
    contrast:['LCA groups people using categorical indicators. Factor analysis groups shared variation among indicators through continuous latent dimensions.','LCA 用類別指標分析人的類型；因素分析則以連續潛在維度表達指標間的共享方差。'],related:['lpa','efa'],sources:['mixture']},
  repeated:{
    idea:['Repeated-measures ANOVA compares means when the same people provide several occasions or conditions. A mixed-design ANOVA also includes a between-person group. Its group-by-time interaction asks whether the pattern of change differs between groups.','重複量數 ANOVA 比較同一批人在多個時點或條件下的平均數；混合設計 ANOVA 再納入個體間組別。組別與時間交互作用問變化模式是否因組別而異。'],
    question:['Do two teaching groups change differently across pre-test, post-test and delayed post-test?','兩種教學組別在前測、後測與延後測之間，是否有不同變化模式？'],
    read:['Plot each group’s means across time. Read the interaction before collapsing results into one overall time effect. Report appropriate df corrections where required, effect sizes and targeted follow-up contrasts with their adjustment.','先繪出各組隨時間的平均數，閱讀交互作用後才考慮整體時間效應。需要時報適當自由度修正、效應量，以及具目標並經調整的後續對比。'],
    check:['For conventional tests with more than two within-person levels, examine sphericity and relevant corrections. Missing occasions, unequal timing and complex dependence may favour a mixed-effects model.','傳統檢定若有多於兩個個體內水平，須檢查球形性與相應修正。缺失時點、時間不等距及複雜依賴，可能更適合混合效應模型。'],
    contrast:['A paired t-test handles a single two-occasion contrast. Mixed-effects models offer more flexible ways to represent individual trajectories and incomplete observations.','配對 t 檢定處理單一的兩時點對比；混合效應模型更靈活地表達個體軌跡及不完整觀察。'],related:['ttest','mixed'],sources:['fein6']},
  growth:{
    idea:['Growth models separate an average trajectory from individual differences in that trajectory. An intercept describes the level at the chosen time origin; a slope describes change per coded time unit. People may differ in both starting level and rate of change.','成長模型區分平均軌跡與個體軌跡差異。截距描述所選時間原點的水平，斜率描述每個編碼時間單位的改變；個體可在起點及變化速率上都有差異。'],
    question:['How does reading proficiency develop over a year, and do learners with different starting levels change at different rates?','閱讀能力在一年內如何發展？起點不同的學習者，其變化速率是否亦不同？'],
    read:['Report time coding, mean intercept and slope, their variances and covariance, uncertainty and trajectory form. Interpret slope units explicitly. A positive mean slope can coexist with considerable variation between learners.','報告時間編碼、截距及斜率平均數、其方差與協方差、不確定性及軌跡形式，明確說明斜率單位。平均斜率為正，仍可伴隨很大的個體差異。'],
    check:['Check enough occasions for the specified curve, model fit, measurement comparability and missing-data assumptions. An average improvement over time is not itself evidence that a particular intervention caused it.','檢查時點是否足以支持指定曲線、模型擬合、測量可比性及缺失假設。平均隨時間進步，不等於某項介入造成進步。'],
    contrast:['Repeated-measures ANOVA compares occasion means. Growth models explicitly represent trajectories and their between-person variation.','重複量數 ANOVA 比較時點平均數；成長模型明確表達軌跡及其個體間差異。'],related:['repeated','mixed'],sources:['growth']},
  clpm:{
    idea:['A CLPM relates later measurements to earlier measurements of the same and another variable. Autoregressive paths capture stability; cross-lagged paths describe lagged associations after prior-score adjustment. The chosen interval defines what “later” means.','CLPM 把較後的測量連到自身及另一变量的較早測量。自迴歸路徑表達穩定性，交叉滯後路徑描述調整先前分數後的滯後關聯；測量間隔決定「其後」的意義。'],
    question:['Does earlier confidence relate to later engagement after adjusting for earlier engagement, and is the reverse association also present?','調整先前投入後，較早信心是否與較後投入有關？反向關聯是否亦存在？'],
    read:['Identify wave timing, autoregressive and cross-lagged paths, within-wave relations and uncertainty. Compare competing temporal specifications where justified. A zero-df two-wave model can fit perfectly without testing meaningful global restrictions.','確認波次時間、自迴歸與交叉滯後路徑、同波關係及不確定性；有理據時比較替代時間模型。兩波零自由度模型可完美擬合，但未檢驗有意義的整體限制。'],
    check:['A standard CLPM can mix stable between-person differences with within-person processes. Temporal precedence and prior-score adjustment do not remove all confounding or establish reciprocal causation.','標準 CLPM 可能混合穩定個體間差異與個體內歷程。時間在先及調整先前分數，不能消除所有混淆或確立雙向因果。'],
    contrast:['RI-CLPM adds a decomposition of stable person differences and within-person deviations, changing the interpretation of lagged paths.','RI-CLPM 再分解穩定個體差異與個體內偏離，從而改變滯後路徑的含義。'],related:['riclpm','growth'],sources:['clpm']},
  riclpm:{
    idea:['RI-CLPM separates each person’s stable level from occasion-specific deviations. Its cross-lagged paths concern deviations from a person’s own expected level, rather than whether generally higher-scoring people differ from generally lower-scoring people.','RI-CLPM 把每人的穩定水平與特定時點偏離分開。其交叉滯後路徑針對相對自身期望水平的偏離，而非一般高分者與低分者之間的差異。'],
    question:['When a learner is more anxious than usual, is their engagement lower than usual at the next wave?','當某學習者比自己平常更焦慮，其下一波投入是否低於自己的平常水平？'],
    read:['Read within-person lagged paths separately from random-intercept correlations and within-wave residual relations. Report timing, equality constraints, uncertainty and the number of waves; the two levels answer different questions.','把個體內滯後路徑、隨機截距相關及同波殘差關係分開閱讀。報時間間隔、相等限制、不確定性及波次數，兩個層次回答不同問題。'],
    check:['The basic model usually requires at least three waves and adequate longitudinal information. Measurement error, time-varying confounding and inappropriate lag intervals remain concerns; the decomposition does not establish causality.','基本模型通常至少需要三波及足夠縱向資訊。測量誤差、隨時間變動的混淆及不合適間隔仍須處理，分解本身不能確立因果。'],
    contrast:['Growth models focus on trajectories. RI-CLPM focuses on lagged relations among within-person deviations around stable levels.','成長模型聚焦軌跡；RI-CLPM 聚焦圍繞穩定水平的個體內偏離之滯後關係。'],related:['clpm','growth'],sources:['panel']},
  timeseries:{
    idea:['Time-series analysis keeps observations in their temporal order. Values close together may be related, and patterns can include trends, cycles or abrupt changes. Plotting the sequence is the starting point; the model depends on the observation frequency and research purpose.','時間序列分析保留觀察的時間次序。相鄰數值可能相關，模式可包含趨勢、週期或突變；應先繪序列圖，再依觀察頻率及研究目的選模型。'],
    question:['How does speaking anxiety fluctuate minute by minute during a task, and are high-anxiety moments followed by similar moments?','任務中的口語焦慮如何逐分鐘波動？高焦慮時刻之後，是否常接續相似時刻？'],
    read:['Report sampling interval, time span, missing observations and preprocessing. Examine time plots and serial-dependence summaries; for forecasting, evaluate errors on later observations that were not used for fitting.','報告取樣間隔、時間跨度、缺失與預處理，閱讀時間圖及序列依賴摘要；若作預測，要在未用來擬合的較後觀察上評估誤差。'],
    check:['Inspect changing mean or variance, timing irregularities and residual autocorrelation. Smoothing can hide meaningful variation. Randomly shuffling time points for validation can leak future information into the past.','檢查平均數或方差的改變、時間不規則及殘差自相關。平滑可能掩蓋重要波動；隨機打亂時間點驗證，可能把未來資訊洩漏到過去。'],
    contrast:['Panel models follow many people over waves. Time-series methods emphasise ordered observations and serial dependence, sometimes within a single person or setting.','面板模型追蹤多人多波資料；時間序列方法強調有序觀察與序列依賴，有時只針對一人或一個情境。'],related:['clpm','gam'],sources:['timeseries']},
  survival:{
    idea:['Survival analysis studies time until a defined event. Right-censored cases contribute information that the event had not occurred by their last observation; they are not coded as having the event then. Survival curves describe remaining event-free over time.','存活分析研究指定事件發生前的時間。右設限個案提供「最後觀察時尚未發生」的資訊，不應把該時間當成事件發生時間；存活曲線描述隨時間尚未發生事件的比例。'],
    question:['How long until learners leave an online course, and how is departure timing related to earlier participation?','學習者多久後離開網課？離開時間與先前參與有何關係？'],
    read:['Define the event, time origin and censoring. Report curves or model-based estimates with uncertainty. In a Cox model, a hazard ratio compares instantaneous event rates among those still at risk; it is not a probability ratio or a ratio of survival times.','界定事件、時間原點及設限，報曲線或模型估計與不確定性。Cox 模型的風險比比較仍在風險集合者的即時事件率，並非機率比或存活時間比。'],
    check:['Examine censoring assumptions and proportional hazards when using Cox regression. Competing events and time-varying predictors need explicit handling rather than being ignored.','檢查設限假設；使用 Cox 模型時亦檢查比例風險。競爭事件及隨時間改變的預測变量須明確處理。'],
    contrast:['Logistic regression asks whether an event occurs by a chosen endpoint. Survival analysis uses its timing and available follow-up information.','邏輯斯迴歸問指定終點前有沒有發生；存活分析使用事件時間及可用追蹤資訊。'],related:['logistic','count'],sources:['survival']},
  mixed:{
    idea:['Mixed-effects models combine population-level coefficients with group- or person-specific deviations. Random intercepts allow different baselines; random slopes allow relationships to vary. The structure can represent repeated learners, pupils within classes, or crossed learners and test items.','混合效應模型結合母體層面係數與組別或個體特有偏離。隨機截距容許起點不同，隨機斜率容許關係改變；可表達重複學習者、學生巢套班級，或學習者與題目的交叉結構。'],
    question:['How does performance change with practice while accounting for repeated scores from learners and differences between test items?','在考慮學習者重複分數及題目差異後，表現如何隨練習改變？'],
    read:['Report fixed effects and intervals, random-effect variances and correlations, grouping factors and the estimation method. For generalised mixed models, identify the family and link, and distinguish conditional from population-average predictions.','報固定效應與區間、隨機效應方差及相關、分組因素與估計法。廣義混合模型須列分佈族與連結，並區分條件預測與母體平均預測。'],
    check:['Check convergence, singular fits, residual patterns and information supporting each random effect. A large number of observations from very few groups does not replace adequate group-level information.','檢查收斂、奇異擬合、殘差模式及各隨機效應的資訊。即使觀察很多，若只來自很少群組，仍不能取代足夠的群組層面資訊。'],
    contrast:['A mixed model explicitly represents group-specific variation. GEE targets marginal, population-average relationships using a working correlation structure.','混合模型明確表達群組特有差異；GEE 以工作相關結構估計邊際母體平均關係。'],related:['gee','repeated'],sources:['mixed']},
  gee:{
    idea:['GEE estimates an average relationship across the population while allowing observations within a cluster to correlate. A working correlation describes that dependence; sandwich uncertainty estimates can tolerate some correlation misspecification under appropriate conditions.','GEE 在容許群組內觀察相關時，估計整體母體的平均關係。工作相關結構描述這種依賴；在適當條件下，三明治式不確定性估計可容忍部分相關結構設定錯誤。'],
    question:['Across learners, how does the probability of participating change over weeks when each learner is observed repeatedly?','同一學習者被反覆觀察時，整體學習者的參與機率如何隨週次改變？'],
    read:['Specify outcome family, link, cluster identifier and working correlation. Report marginal coefficients or interpretable predicted means, robust intervals and the number of independent clusters. Explain what population-average means for the question.','列明結果分佈族、連結、群組識別及工作相關，報邊際係數或易解釋的預測平均、穩健區間與獨立群組數，並說明母體平均對研究問題的意義。'],
    check:['Robust standard errors rely on adequate independent clusters; few clusters may require corrections. Mean-model misspecification and informative missingness are not automatically repaired by a working correlation.','穩健標準誤需要足夠獨立群組；群組少時可能須修正。工作相關不會自動修補平均模型錯誤或具資訊性的缺失。'],
    contrast:['GEE and mixed models can answer different questions, especially with nonlinear links. A population-average odds ratio need not equal a subject-specific odds ratio.','尤其使用非線性連結時，GEE 與混合模型可回答不同問題；母體平均勝算比不必等於個體特定勝算比。'],related:['mixed','logistic'],sources:['gee']},
  network:{
    idea:['In a conditional-association network, variables are nodes and estimated conditional relations are edges. A partial-correlation edge describes association after conditioning on the other included variables. Its meaning depends on the node set, measurement and model.','條件關聯網絡以变量為節點，以估計的條件關係為邊。偏相關邊描述以其餘納入变量為條件後的關聯；含義取決於節點集合、測量與模型。'],
    question:['Which aspects of anxiety and engagement remain associated after accounting for the other measured aspects?','在考慮其他已測面向後，焦慮與投入的哪些面向仍有關聯？'],
    read:['Report the model, node definitions, estimator and regularisation choices. Read edge signs and weights with their uncertainty; inspect edge accuracy and centrality stability before ranking nodes. Visual closeness is not a statistical test.','報模型、節點定義、估計法及正則化選擇。閱讀邊的正負、權重及不確定性；排名節點前檢查邊的準確度與中心性穩定性。視覺上靠近並非統計檢定。'],
    check:['An undirected edge does not identify a causal direction or an intervention target. Similar items, omitted variables and sampling variation can strongly affect edges and apparent centrality.','無向邊不能識別因果方向或介入目標；相似題目、遺漏变量及抽樣波動可明顯影響邊與表面中心性。'],
    contrast:['Factor models represent shared variation through latent variables. Network models represent specified conditional relations among the observed nodes.','因素模型以潛在变量表達共享方差；網絡模型表達觀察節點間指定的條件關係。'],related:['efa','correlation'],sources:['network']},
  forest:{
    idea:['Tree ensembles combine many decision trees to improve prediction. Random forests fit varied trees and aggregate their predictions; boosting adds trees sequentially to improve the current model. Both can capture nonlinearities and interactions without specifying every one in advance.','樹集成模型結合多棵決策樹改善預測。隨機森林擬合不同樹並整合預測；提升法依次加樹改善目前模型。兩者可捕捉非線性及交互作用，毋須逐一事先指定。'],
    question:['Can baseline learning measures predict which new learners will need additional support?','能否用起始學習量度，預測哪些新學習者需要額外支援？'],
    read:['Compare held-out performance with a simple baseline using task-appropriate metrics. Report tuning, the validation split and uncertainty. Feature importance concerns model prediction and depends on the importance measure; it is not a causal effect.','用合適指標把保留資料表現與簡單基準比較，報調參、驗證劃分及不確定性。特徵重要性關乎模型預測，且依重要性定義而異，並非因果效應。'],
    check:['Keep learners or classes together across splits when observations are dependent. Fit preprocessing only on training data. Examine class imbalance, calibration and subgroup performance rather than training accuracy alone.','觀察有依賴時，劃分資料須把同一學習者或班級留在同一組；預處理只能用訓練資料擬合。檢查類別不平衡、校準及子群表現，不只看訓練準確度。'],
    contrast:['Regression coefficients summarise a specified relationship. Tree ensembles prioritise predictive performance; their flexibility can reduce interpretability.','迴歸係數概括指定關係；樹集成以預測表現為重，其彈性可能降低易解釋程度。'],related:['regression','svm'],sources:['forest']},
  svm:{
    idea:['A support vector classifier seeks a boundary that separates labelled cases with a large margin, while permitting controlled errors. Kernels allow nonlinear boundaries. Support vector regression uses a related approach for continuous outcomes.','支持向量分類器尋找具有大間隔、可分開已標記個案的邊界，同時容許受控制的錯誤。核函數可形成非線性邊界；支持向量迴歸以相關方法處理連續結果。'],
    question:['Can linguistic features distinguish new essays meeting a proficiency threshold from those below it?','語言特徵能否區分達到能力門檻與未達門檻的新作文？'],
    read:['Report scaling, kernel, tuning procedure and held-out metrics appropriate to the class balance and decision costs. A decision score is not automatically a calibrated probability; probability estimates need separate attention.','報尺度處理、核函數、調參方式及配合類別比例與決策代價的保留資料指標。決策分數不會自動等同校準機率；機率估計須另外處理。'],
    check:['Tune only inside training folds and keep repeated writers or prompts from leaking across splits. Compare performance with a simpler model and inspect generalisation to the intended population.','只在訓練摺內調參，避免同一作者或題目跨組洩漏。與較簡單模型比較，並檢查對預定母體的概化。'],
    contrast:['Logistic regression directly specifies a probability model. SVM classification centres on a separation margin and may require additional probability calibration.','邏輯斯迴歸直接指定機率模型；SVM 分類以分隔間隔為中心，可能需額外機率校準。'],related:['logistic','forest'],sources:['svm']},
  neural:{
    idea:['Neural networks learn successive transformations of inputs before producing a prediction. Hidden layers can represent complex patterns, but greater complexity also increases the opportunity to fit accidental features of the training data.','神經網絡學習輸入的逐層轉換，再產生預測。隱藏層可表達複雜模式，但複雜度增加亦提高擬合訓練資料偶然特徵的機會。'],
    question:['Can a model trained on text or speech predict human ratings for new learners and new tasks?','以文字或語音訓練的模型，能否預測新學習者及新任務的人類評分？'],
    read:['Report inputs, architecture, training data and tuning, then held-out accuracy or error against a baseline. Include calibration or agreement where relevant, variation across runs and performance across important subgroups.','報輸入、架構、訓練資料及調參，再報相對基準的保留資料準確度或誤差；適用時包括校準或一致性、不同訓練次數的差異及重要子群表現。'],
    check:['Prevent learner, prompt and outcome-label leakage. Inspect overfitting, representativeness and domain shift. High agreement with ratings does not itself establish that the model measures the intended construct fairly.','避免學習者、題目及結果標籤洩漏；檢查過度擬合、代表性與領域轉移。與人類評分高度一致，本身不能確立模型公平量度了預定構念。'],
    contrast:['Neural networks learn layered representations. A simpler regression or tree model may offer a stronger practical baseline when data or interpretability are limited.','神經網絡學習多層表徵；資料或解釋需求受限時，簡單迴歸或樹模型可能是更有用的實務基準。'],related:['forest','regression'],sources:['neural']},
  meta:{
    idea:['Random-effects meta-analysis combines comparable study effects while allowing their underlying effects to vary. Each estimate contributes according to its uncertainty and the modelled heterogeneity; the synthesis is not a vote count of significant results.','隨機效應統合分析整合可比較的研究效應，同時容許真正效應因研究而異。各估計的貢獻取決於其不確定性與模型異質性，並非點算有多少研究顯著。'],
    question:['Across eligible studies, what is the average association between feedback and writing improvement, and how much do effects vary?','在符合條件的研究中，回饋與寫作改善的平均關聯如何？效果有多大差異？'],
    read:['Report the effect metric, study count, estimator, pooled estimate and interval. Read τ², I² and a prediction interval when appropriate. The pooled interval describes uncertainty about an average, not the spread of effects expected across settings.','報效應指標、研究數、估計法、綜合估計與區間，再讀 τ²、I² 及適當的預測區間。綜合區間表達平均效應的不確定性，並非不同情境效果的分佈範圍。'],
    check:['Check study eligibility, comparable estimands, bias, missing results and dependent effects. Random effects do not make incompatible outcomes or poor studies automatically comparable.','檢查納入條件、目標量可比性、偏差、缺失結果及效果依賴。隨機效應不能自動令不相容結果或低質研究變得可比。'],
    contrast:['Meta-analysis combines study estimates. A primary-data regression analyses individual observations; the unit and uncertainty structure differ.','統合分析結合研究估計；原始資料迴歸分析個別觀察，兩者單位與不確定性結構不同。'],related:['metareg','multimeta'],sources:['meta']},
  metareg:{
    idea:['Meta-regression relates differences in study effect estimates to study-level characteristics. It extends synthesis by asking which measured study features accompany larger or smaller effects, while retaining sampling uncertainty and residual heterogeneity.','統合迴歸把研究效應估計的差異連到研究層面特徵，在保留抽樣不確定性及剩餘異質性的情況下，探討哪些研究特徵伴隨較大或較小效果。'],
    question:['Do studies with longer feedback interventions tend to report larger effect estimates?','回饋介入時間較長的研究，是否傾向報較大的效應估計？'],
    read:['Report moderator coding, coefficients and intervals, number of studies per comparison and residual heterogeneity. Explain the effect metric: a slope is a change in that metric per unit of the study-level moderator.','報調節变量編碼、係數及區間、各比較的研究數與剩餘異質性。交代效應指標：斜率是研究層面調節变量每增加一單位，該指標改變多少。'],
    check:['Few studies, correlated moderators and selective exploration can produce unstable findings. A study-level association does not establish the corresponding individual-level relationship or a causal moderator effect.','研究少、調節变量相關及選擇性探索，可產生不穩定結果。研究層面關聯不能確立相應的個體層面關係或因果調節效應。'],
    contrast:['An ordinary subgroup summary describes groups separately. Meta-regression can directly model and test their contrast or a continuous study characteristic.','一般子群摘要分別描述各組；統合迴歸可直接建模並檢驗其對比，或分析連續研究特徵。'],related:['meta','moderation'],sources:['metareg']},
  multimeta:{
    idea:['Several effect estimates from one study often share participants or comparisons. Multilevel meta-analysis models sources of effect variation; robust variance estimation adjusts inference for clustered effects. These address related but distinct parts of dependence.','同一研究的多個效應常共享參與者或比較組。多層統合分析建模不同來源的效應差異；穩健方差估計調整群集效應的推論。兩者處理依賴的不同但相關部分。'],
    question:['How can several outcomes and follow-up effects from each feedback study be synthesised without pretending they are independent studies?','如何統合各回饋研究的多個結果及追蹤效應，而不把它們假當作獨立研究？'],
    read:['Report effects and independent studies separately, the sampling covariance assumptions, random-effect levels and variance components. For robust inference, state the cluster definition and small-sample correction or effective df.','分別報效應數與獨立研究數、抽樣協方差假設、隨機效應層次及方差成分。穩健推論須列群組定義、小樣本修正或有效自由度。'],
    check:['A study random intercept does not automatically represent all shared sampling error. Very few independent studies can still make robust inference unreliable; sensitivity to unknown correlations should be examined.','研究隨機截距不會自動表達所有共享抽樣誤差。獨立研究很少時，穩健推論仍可能不可靠；須檢視對未知相關的敏感度。'],
    contrast:['A conventional meta-analysis commonly assumes independent effect estimates. Multilevel models and robust inference explicitly address relevant forms of dependence.','傳統統合分析通常假設效應估計獨立；多層模型與穩健推論明確處理相關依賴形式。'],related:['meta','mixed'],sources:['multimeta','rve']},
  bayes:{
    idea:['Bayesian estimation combines a prior distribution with the likelihood to obtain a posterior distribution. The posterior expresses parameter uncertainty conditional on the data, prior and model. It is an estimation framework that can be used with regression, multilevel and many other models.','貝葉斯估計結合先驗分佈與似然，取得後驗分佈。後驗表達以資料、先驗與模型為條件的參數不確定性；它是可配合迴歸、多層等模型的估計框架。'],
    question:['Given a defensible prior and the observed scores, what values of the group difference remain plausible under the model?','在合理先驗及觀察分數下，模型支持哪些組別平均差數值？'],
    read:['Report priors, likelihood, posterior summaries and the chosen credible interval definition. Examine posterior predictive checks. For simulation-based estimation, report convergence and sampling diagnostics such as R-hat, effective sample size and divergences where applicable.','報先驗、似然、後驗摘要與可信區間定義，檢視後驗預測檢查。若用模擬估計，須報收斂與抽樣診斷，例如 R-hat、有效樣本數及適用的發散情況。'],
    check:['Inspect sensitivity to consequential prior choices and whether simulated outcomes resemble the observed data. A Bayesian analysis is not assumption-free, and posterior probabilities remain conditional on the chosen model.','檢查對重要先驗選擇的敏感度，以及模擬結果是否像觀察資料。貝葉斯分析並非沒有假設，後驗機率仍以所選模型為條件。'],
    contrast:['A credible interval has a posterior-probability interpretation under the model. A frequentist confidence interval is defined by a repeated-sampling coverage procedure.','可信區間在模型下有後驗機率含義；頻率學派置信區間則由重複抽樣涵蓋率程序界定。'],related:['regression','resampling'],sources:['bayes']},
  resampling:{
    idea:['Resampling repeats an analysis on deliberately generated datasets. A nonparametric bootstrap samples cases with replacement to approximate sampling variation. A permutation test rearranges labels or values under a justified null scheme. These procedures answer different questions.','重抽樣在刻意生成的資料集上重複分析。非參數自助法有放回地抽個案，近似抽樣波動；排列檢定依合理零假設方案重排標籤或數值。兩種程序回答不同問題。'],
    question:['How uncertain is an indirect estimate whose sampling distribution may be asymmetric? Or how unusual is a group contrast under a valid label-exchange scheme?','若間接估計的抽樣分佈不對稱，其不確定性如何？或在有效標籤交換方案下，組別差值有多罕見？'],
    read:['State the statistic, resampling unit, number of replicates, interval or test procedure and random seed. A bootstrap interval can be asymmetric; different interval methods need not agree. Report the actual method rather than “bootstrapping was used”.','列明統計量、重抽樣單位、重複次數、區間或檢定程序及隨機種子。自助區間可不對稱，不同區間方法也可能不同；不要只寫「使用了自助法」。'],
    check:['Preserve pairs, clusters or time dependence as the design requires. More replicates reduce simulation noise but do not fix biased sampling, a wrong model or resampling at the wrong level.','依設計保留配對、群集或時間依賴。增加重複次數可降低模擬雜訊，但不能修補偏頗取樣、錯誤模型或錯誤重抽樣層次。'],
    contrast:['Bootstrap approximates uncertainty under a sampling model. Permutation inference relies on the exchangeability or randomisation justified by its null design.','自助法在抽樣模型下近似不確定性；排列推論依賴零假設設計所支持的可交換性或隨機分派。'],related:['mediation','bayes'],sources:['resampling']},
};
